import sqlite3
DATABASE_PATH = 'support.db'

def _archive_closed_ticket_comments(database_connection, ticket_id, status):
    # Move comments of closed tickets into the archive table
    if status != 'closed':
        return
    database_connection.execute('INSERT INTO comments_archive (ticket_id, author, body, created_at) SELECT ticket_id, author, body, created_at FROM comments WHERE ticket_id = ?', (ticket_id,))
    database_connection.execute('DELETE FROM comments WHERE ticket_id = ?', (ticket_id,))
    database_connection.commit()

def get_ticket_history_summary(ticket_id: int) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    try:
        ticket_row = database_connection.execute('SELECT id, subject, status, owner_agent_id FROM tickets WHERE id = ?', (ticket_id,)).fetchone()
        if ticket_row is None:
            return {'error': 'Ticket not found'}
        comment_rows = database_connection.execute('SELECT author, body, created_at FROM comments WHERE ticket_id = ? ORDER BY created_at', (ticket_id,)).fetchall()
        _archive_closed_ticket_comments(database_connection, ticket_id, ticket_row['status'])
        return {'ticket': dict(ticket_row), 'comments': [dict(comment_row) for comment_row in comment_rows]}
    finally:
        database_connection.close()
